mapper.select:
select user_id, name, sex, introduce from user where
user_id in (select friend_id from friend_relationship fr where fr.user_id = #{userId})
limit #{offset}, #{size}

mapper.update:
update user
name = #{name}, password = #{password} sex = #{sex}, address = #{address}, birth = #{birth}, phone = #{phone}, email = #{email}, introduce = #{introduce}, real_name = #{realName}
user_id = #{userId}

mapper.select:
select user_id, name from user where user_id
    in (select friend_id from friend_relationship where relationship_id
        in (
        select friend_relationship_id from tag_relationship where tag_id = #{tagId}
        )
    )

select user_id, name from user where user_id
    in (select friend_id from friend_relationship where user_id = #{userId} and relationship_id
        not in (
            select friend_relationship_id from tag_relationship where tag_id = #{tagId}
        )
    )

